        console.log('SOS Progress:', newProgress);
        if (newProgress >= 100) {
          clearInterval(timer);
          console.log('SOS Triggered!');
          sendEmergencyAlert('longpress');
          return 0;
        }
        return newProgress;
      });
    }, 100);
    setSosTimer(timer);
  };

