                </div>
              )}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: theme.text, fontSize: '14px' }}>📳 Auto Shake SOS</span>
                  <button 
                    onClick={() => setShakeEnabled(!shakeEnabled)}
                    style={{
                      background: shakeEnabled ? '#34c759' : '#8e8e93',
                      color: 'white',
                      border: 'none',
                      borderRadius: '15px',
                      padding: '4px 12px',
                      fontSize: '12px'
                    }}
                  >
                    {shakeEnabled ? 'ACTIVE' : 'OFF'}
                  </button>
                </div>
                {(shakeSequence.length > 0 || laptopShakes.length > 0) && (
                  <div style={{
                    background: (shakeSequence.length >= 2 || laptopShakes.length >= 2) ? '#ff3b30' : '#ff9500',
                    color: 'white',
                    padding: '10px',
                    borderRadius: '10px',
                    marginTop: '10px',
                    fontSize: '14px',
                    textAlign: 'center',
                    fontWeight: 'bold'
                  }}>
                    {shakeSequence.length > 0 ? (
                      `📱 ${shakeSequence.length}/3 ${shakeSequence.length >= 2 ? '🚨' : ''}`
                    ) : (
                      `💻 ${laptopShakes.length}/3 ${laptopShakes.length >= 2 ? '🚨' : ''}`
                    )}
                  </div>
                )}

                <div style={{
                  background: '#e3f2fd',
                  padding: '10px',
                  borderRadius: '8px',
                  marginTop: '10px',
                  fontSize: '12px',
                  color: '#1976d2'
                }}>
                  📱💻 Auto SOS Detection<br/>
                  • Mobile: Shake device 3x<br/>
                  • Laptop: Move/tilt laptop 3x
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: theme.text, fontSize: '14px' }}>🎤 Voice Detection</span>
                  <span style={{ color: isListening ? '#34c759' : '#8e8e93', fontSize: '12px', fontWeight: '500' }}>
                    {isListening ? 'LISTENING' : 'READY'}
                  </span>
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <span style={{ color: theme.text, fontSize: '14px' }}>📶 Offline SOS</span>
                  <span style={{ color: !isOnline ? '#ff3b30' : '#34c759', fontSize: '12px', fontWeight: '500' }}>
                    {!isOnline ? (offlineAlertSent ? 'SENT' : 'TRIGGERED') : 'READY'}
                  </span>
                </div>
              </div>
            </div>

            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              marginBottom: '20px',
              boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)'
            }}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '18px', color: theme.text, fontWeight: '600' }}>
                🚨 Emergency Helplines
              </h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                {[
                  { name: 'Police', number: '100', icon: '👮' },
                  { name: 'Women Helpline', number: '1091', icon: '👩' },
                  { name: 'Ambulance', number: '108', icon: '🚑' },
                  { name: 'Fire Brigade', number: '101', icon: '🚒' }
                ].map((helpline) => (
                  <div key={helpline.number} style={{ 
                    display: 'flex', 
                    justifyContent: 'space-between', 
                    alignItems: 'center',
                    padding: '8px 0'
                  }}>
                    <span style={{ color: theme.text, fontSize: '14px' }}>
                      {helpline.icon} {helpline.name}
                    </span>
                    <button
                      onClick={() => window.open(`tel:${helpline.number}`)}
                      style={{
                        background: '#ff3b30',
                        color: 'white',
                        border: 'none',
                        padding: '6px 12px',
                        borderRadius: '8px',
                        fontSize: '14px',
                        fontWeight: '500',
                        cursor: 'pointer'
                      }}
                    >
                      📞 {helpline.number}
                    </button>
                  </div>
                ))}
              </div>
            </div>

            <div style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '20px',
              boxShadow: isDark ? 'none' : '0 8px 25px rgba(0,0,0,0.08)'
            }}>
              <h3 style={{ margin: '0 0 15px 0', fontSize: '18px', color: theme.text, fontWeight: '600' }}>
                💡 Safety Tips
              </h3>
              <div style={{ fontSize: '14px', lineHeight: '1.8', color: theme.subtext }}>
                <p style={{ margin: '0 0 8px 0' }}>🔹 3 movements in 2 seconds = Auto SOS</p>
                <p style={{ margin: '0 0 8px 0' }}>🔹 Auto-calls + SMS emergency contacts</p>
                <p style={{ margin: '0 0 8px 0' }}>🔹 Works on mobile + laptop</p>
                <p style={{ margin: '0' }}>🔹 No manual clicks required</p>
              </div>
            </div>
          </div>
        );
    }
  };

  return (
    <div style={{ 
      background: theme.gradient,
      minHeight: '100vh',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
      margin: '0',
      padding: '0',
      maxWidth: '414px',
      marginLeft: 'auto',
      marginRight: 'auto',
      position: 'relative',
      boxShadow: isDark ? 'none' : '0 0 20px rgba(0,0,0,0.1)'
    }}>

      {/* Firebase Notification Popup */}
      {notification && (
        <div style={{
          position: 'fixed',
          top: '60px',
          left: '20px',
          right: '20px',
          background: '#ff3b30',
          color: 'white',
          padding: '15px',
          borderRadius: '15px',
          zIndex: '9999',
          boxShadow: '0 10px 30px rgba(255, 59, 48, 0.3)'
        }}>
          <div style={{ fontWeight: '600', marginBottom: '5px' }}>{notification.title}</div>
          <div style={{ fontSize: '14px', opacity: '0.9' }}>{notification.body}</div>
          <button
            onClick={clearNotification}
            style={{
              position: 'absolute',
              top: '10px',
              right: '10px',
              background: 'rgba(255,255,255,0.2)',
              border: 'none',
              color: 'white',
              borderRadius: '50%',
              width: '24px',
              height: '24px',
              cursor: 'pointer'
            }}
          >
            ×
          </button>
        </div>
      )}

      <div style={{
        background: isDark ? 'rgba(0,0,0,0.9)' : 'rgba(255,255,255,0.9)',
        backdropFilter: 'blur(20px)',
        padding: '8px 20px 5px 20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        fontSize: '14px',
        fontWeight: '600',
        color: theme.text,
        borderBottom: `1px solid ${theme.border}`,
        position: 'sticky',
        top: '0',
        zIndex: '1000'
      }}>
        <div>9:41</div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
          <span style={{ color: isOnline ? '#34c759' : '#ff3b30', fontSize: '12px' }}>
            {isOnline ? '●' : '●'} {isOnline ? 'Online' : (offlineAlertSent ? 'SOS Sent' : 'Offline')}
          </span>
          <span style={{ color: isConnected ? '#34c759' : '#ff9500', fontSize: '12px' }}>
            🔥 {isConnected ? 'Firebase' : 'Connecting'}
          </span>
          {battery && (
            <span style={{ fontSize: '12px' }}>🔋{battery}%</span>
          )}
          <span>📶</span>
        </div>
      </div>

      <div style={{
        background: isDark ? 'rgba(28,28,30,0.95)' : 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        padding: '20px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderBottom: `1px solid ${theme.border}`
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <NivraLogo size={40} />
          <div>
            <h1 style={{ margin: '0', color: '#8A2BE2', fontSize: '28px', fontWeight: '700' }}>NIVRA</h1>
            <p style={{ margin: '2px 0 0 0', color: theme.subtext, fontSize: '14px' }}>
              Hi, {currentUser?.fullName?.split(' ')[0] || 'User'}! 👋
            </p>
          </div>
        </div>
        <div style={{ display: 'flex', gap: '10px' }}>
          <button 
            onClick={() => setIsDark(!isDark)}
            style={{
              background: theme.cardBg,
              border: `1px solid ${theme.border}`,
              borderRadius: '20px',
              padding: '8px 12px',
              fontSize: '16px',
              cursor: 'pointer'
            }}
          >
            {isDark ? '☀️' : '🌙'}
          </button>
          <button 
            onClick={() => setShowProfile(!showProfile)}
            style={{
              background: '#ff6b9d',
              color: 'white',
              border: 'none',
              borderRadius: '20px',
              padding: '8px 16px',
              fontSize: '14px',
              fontWeight: '500',
              cursor: 'pointer'
            }}
          >
            👤
          </button>
        </div>
      </div>



      <div style={{ 
        padding: '20px',
        paddingBottom: '100px',
        background: theme.bg,
        minHeight: 'calc(100vh - 140px)',
        position: 'relative'
      }}>
        {/* Floating Buttons */}
        <div style={{
          position: 'absolute',
          right: '10px',
          top: '50%',
          transform: 'translateY(-50%)',
          display: 'flex',
          flexDirection: 'column',
          gap: '10px',
          zIndex: '100'
        }}>
          {/* Chatbot Button */}
          <button 
            onClick={() => setCurrentPage('chat')}
            style={{
              width: '50px',
              height: '50px',
              borderRadius: '50%',
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              border: 'none',
              color: 'white',
              fontSize: '20px',
              cursor: 'pointer',
              boxShadow: '0 4px 12px rgba(102, 126, 234, 0.3)',
              transition: 'transform 0.2s'
            }}
            onMouseDown={(e) => e.target.style.transform = 'scale(0.9)'}
            onMouseUp={(e) => e.target.style.transform = 'scale(1)'}
            title="AI Chatbot"
          >
            🤖
          </button>

          {/* SOS Button */}
          <button 
            onMouseDown={startSosTimer}
            onMouseUp={stopSosTimer}
            onTouchStart={startSosTimer}
            onTouchEnd={stopSosTimer}
            onClick={() => {
              console.log('SOS Button clicked');
              const emergencyContacts = JSON.parse(localStorage.getItem('emergencyContacts') || '[]');

              if (emergencyContacts.length === 0) {
                alert('⚠️ No emergency contacts found!\nPlease add emergency contacts first.');
                setCurrentPage('contacts');
                return;
              }

              console.log('Emergency contacts:', emergencyContacts);

              // Test direct call first
              const firstContact = emergencyContacts[0];
              console.log('Calling first contact:', firstContact);

              if (window.confirm(`🚨 EMERGENCY\n\nCall ${firstContact.name}?\n${firstContact.phone}`)) {
                console.log('User confirmed call');
                window.location.href = `tel:${firstContact.phone}`;

                // Auto send SMS via backend API
                setTimeout(async () => {
                  const message = `EMERGENCY: ${currentUser?.fullName || 'User'} needs help! Call immediately. Location: ${address || 'Unknown'}`;

                  try {
                    console.log('Sending automatic SMS via backend...');

                    const response = await fetch('http://localhost:5000/api/emergency/send-sms', {
                      method: 'POST',
                      headers: {
                        'Content-Type': 'application/json',
                        'Authorization': `Bearer ${localStorage.getItem('token')}`
                      },
                      body: JSON.stringify({
                        contacts: emergencyContacts,
                        message: message,
                        alertData: {
                          type: 'sos',
                          userInfo: { name: currentUser?.fullName },
                          location: { address: address },
                          timestamp: new Date().toLocaleString()
                        }
                      })
                    });

                    const result = await response.json();

                    if (response.ok) {
                      console.log('SMS sent successfully:', result);
                      const contactNames = emergencyContacts.map(c => c.name).join(', ');
                      alert(`✅ Emergency SMS sent automatically to:\n${contactNames}`);
                    } else {
                      throw new Error(result.message || 'SMS sending failed');
                    }

                  } catch (error) {
                    console.error('Auto SMS failed:', error);
                    alert('❌ Auto SMS failed. Please call contacts manually.');
                  }
                }, 500);
              }
            }}
            style={{
              width: '50px',
              height: '50px',
              borderRadius: '50%',
              background: sosProgress > 0 ? `conic-gradient(#34c759 ${sosProgress * 3.6}deg, #ff416c 0deg)` : 'linear-gradient(135deg, #ff416c 0%, #ff4b2b 100%)',
              border: 'none',
              color: 'white',
              fontSize: '14px',
              fontWeight: 'bold',
              cursor: 'pointer',
              boxShadow: '0 4px 12px rgba(255, 65, 108, 0.3)',
              transition: 'transform 0.2s'
            }}
            onMouseDown={(e) => e.target.style.transform = 'scale(0.9)'}
            onMouseUp={(e) => e.target.style.transform = 'scale(1)'}
            title={sosProgress > 0 ? `Hold... ${Math.round(sosProgress)}%` : 'Emergency SOS - Click to test'}
          >
            🆘
          </button>
        </div>
        {renderPage()}
      </div>



      <div style={{
        position: 'fixed',
        bottom: '0',
        left: '50%',
        transform: 'translateX(-50%)',
        width: '100%',
        maxWidth: '414px',
        background: isDark ? 'rgba(28,28,30,0.95)' : 'rgba(255,255,255,0.95)',
        backdropFilter: 'blur(20px)',
        borderTop: `1px solid ${theme.border}`,
        padding: '10px 0 25px 0',
        display: 'flex',
        justifyContent: 'space-around',
        alignItems: 'center'
      }}>
        <button 
          onClick={() => setCurrentPage('home')}
          style={{ 
            background: currentPage === 'home' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >🏠</button>

        <button 
          onClick={() => setCurrentPage('map')}
          style={{ 
            background: currentPage === 'map' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >📍</button>

        <button 
          onClick={() => setCurrentPage('settings')}
          style={{ 
            background: currentPage === 'settings' ? '#ff6b9d' : 'none', 
            border: 'none', 
            padding: '10px', 
            fontSize: '24px', 
            cursor: 'pointer',
            borderRadius: '12px'
          }}
        >⚙️</button>
      </div>
    </div>
  );
};

export default Dashboard;
